  ('f4e577fe-a6e7-58ae-b9f4-6d1679ce545d', 'hamburguesa', 'noun', 'burger', null, 'neutral', false, null, 'draft'),
  ('2d315bfa-1d08-5359-a1e1-8eddfa4f9040', 'pancho', 'noun', 'hot dog', null, 'neutral', false, null, 'draft'),
  ('1fdb8f27-1f07-545b-9322-4db1bb2e21ca', 'sándwich de miga', 'noun', 'thin sandwich without crust', 'Very thin white bread, usually with ham and cheese. Every café and bakery sells it.', 'neutral', false, null, 'draft'),
  ('e5a72923-737d-5130-87c6-73e1a4045862', 'capo', 'noun', 'the best, a great person', '"Sos un capo" is strong praise, often a way to say thanks.', 'informal', false, null, 'draft'),
  ('7a113a93-b736-5005-b0cf-9d03e7bc856f', 'mala mía', 'phrase', 'my mistake', 'A quick, casual way to say something was your fault.', 'informal', false, null, 'draft'),
  ('f78d15b7-5ee4-5500-8d56-1e629062e4f0', 'no importa', 'phrase', 'it doesn''t matter', null, 'neutral', false, null, 'draft'),
  ('90e32b7c-9407-5e3d-b5e2-6c31bf0e5f50', 'no hay problema', 'phrase', 'no problem', null, 'neutral', false, null, 'draft'),
  ('e62bd1f2-5996-55c9-94c1-92b0916150ea', 'bien ahí', 'interj', 'nice one, well done', null, 'informal', false, null, 'draft'),
  ('54c52cdd-fcf5-5982-b7fe-39e3d91a6bb9', 'pucha', 'interj', 'oh no', 'A soft, polite way to show you are sorry or let down.', 'informal', false, null, 'draft'),
  ('78b8f0c4-598d-5dd8-96f7-3be3d852475e', 'por supuesto', 'phrase', 'of course', null, 'neutral', false, null, 'draft'),
  ('78cd85f3-3bb1-5604-9602-ae267e20457b', 'de vuelta', 'adv', 'again', 'What people say here for "again".', 'neutral', false, null, 'draft'),
  ('6028290e-2862-5681-9a95-33ef16979c61', 'el interior', 'noun', 'the rest of the country (outside Buenos Aires)', 'Everything that is not Buenos Aires. People from the city say it a lot.', 'neutral', false, null, 'draft'),
  ('3a4e3274-177a-5629-9722-609373d23f07', 'hombre', 'noun', 'man', null, 'neutral', false, null, 'draft'),
  ('a9cdccf7-0302-561a-b2d7-87f554f2cf84', 'una masa', 'phrase', 'great (a great person or thing)', 'Does not change for a man or a woman: "mi hermana es una masa".', 'informal', false, null, 'draft'),
  ('dc522934-635e-514c-9dac-d20dada1ea60', 'edad', 'noun', 'age', null, 'neutral', false, null, 'draft'),
  ('5fd626da-0425-5f11-8e40-e2558d44e201', 'ufa', 'interj', 'ugh', 'A sound for when you are annoyed or bored, like a sigh.', 'informal', false, null, 'draft'),
  ('d7802ce6-27bf-5a64-92a1-11c5160a13ce', 'es un montón', 'phrase', 'that''s a lot', null, 'informal', false, null, 'draft'),
  ('ea30c855-98e0-5bd6-97a8-c17dde1ebc6e', 'rulos', 'noun', 'curls, curly hair', null, 'neutral', false, null, 'draft'),
  ('7d70758a-4269-58ac-8090-73a77aed1535', 'pintón', 'adj', 'good-looking', null, 'informal', false, null, 'draft'),
  ('80ddea8c-5903-566c-ab79-26c38777d5f0', 'computadora', 'noun', 'computer', 'The full word. In everyday talk people say compu.', 'neutral', false, null, 'draft'),
  ('f904d9fc-18aa-511e-8a71-13c830c54d81', 'nabo', 'noun', 'fool (soft and friendly)', 'A soft word, often said about yourself: "¡qué nabo!".', 'informal', false, null, 'draft'),
  ('f62bb10a-04e9-5f31-a173-92834ea7a4c5', 'moto', 'noun', 'motorbike', null, 'neutral', false, null, 'draft'),
  ('e102a654-5e38-5869-836e-cbcd4dda3234', 'bicicleta', 'noun', 'bicycle', null, 'neutral', false, null, 'draft'),
  ('ac5527c2-7ed5-5891-9576-b17f6cc1337d', 'coso', 'noun', 'thing (when you don''t know the word)', 'For any object when you forget its name.', 'informal', false, null, 'draft'),
  ('56938bbc-1cba-5dce-916f-b7b670e32320', 'una banda', 'phrase', 'a lot', '"Una banda de gente" is a lot of people.', 'informal', false, null, 'draft'),
  ('48ede574-33f8-592e-8f05-8382c0fa1ebe', 'está bueno', 'phrase', 'it''s good, it''s nice', 'For a thing or a place. About a person it means good-looking.', 'informal', false, null, 'draft'),
  ('49833042-a14c-5041-8932-e28f4a2035a8', 'joda', 'noun', 'party', null, 'informal', false, null, 'draft'),
  ('91700260-67c8-565c-9289-6b1866894781', 'cómo va', 'phrase', 'how''s it going?', null, 'neutral', false, null, 'draft'),
  ('ff06e541-cb08-52ba-94dc-c54fd8370132', 'todo tranqui', 'phrase', 'all calm, all good', null, 'neutral', false, null, 'draft'),
  ('acc06399-48ef-5890-a10e-423a0e6d551f', 'hecho pelota', 'adj', 'very tired; very sad', 'Stronger than cansado.', 'informal', false, null, 'draft'),
  ('bbabc28d-4c42-5ffb-a047-48e941448115', 'acá andamos', 'phrase', 'getting by, not bad', 'A common answer when things are just OK.', 'neutral', false, null, 'draft'),
  ('653a0ddb-e935-59b3-bf5e-881f3f1eeef6', 'a mil', 'phrase', 'very busy', 'Said with estar: "estoy a mil".', 'informal', false, null, 'draft'),
  ('be35325e-e3ee-50d4-a81a-ecdbfa6f9853', 'denso', 'adj', 'annoying, tiring (a person)', 'Someone who keeps asking or will not stop talking.', 'informal', false, null, 'draft'),
  ('7dd3b290-fcba-516f-bd54-8b24567d3802', 'bastante', 'adv', 'quite; enough', null, 'neutral', false, null, 'draft'),
  ('8269eeb4-c2be-5b38-b288-efffdf89cbb5', 'demasiado', 'adv', 'too, too much', null, 'neutral', false, null, 'draft'),
  ('8a83f15d-6510-5be2-967f-bcea6afcb47a', 'tacho', 'noun', 'trash can', 'Any bin, at home or in the street.', 'neutral', false, null, 'draft'),
  ('9ee6d01a-21b0-5118-b5b4-bc539659a0d4', 'qué hacés', 'interj', 'hi, how''s it going?', 'As a greeting it is not a real question. Answer "todo bien, ¿y vos?".', 'informal', false, null, 'draft'),
  ('0915b5dd-f5e4-5633-9c1b-2120531ca7a7', 'microcentro', 'noun', 'the business center of Buenos Aires', null, 'neutral', false, null, 'draft'),
  ('41a11fdb-5b81-5e5d-849f-c18984fce912', 'universidad', 'noun', 'university', null, 'neutral', false, null, 'draft'),
  ('67f7a478-fabc-5a1d-a870-bc8b44403416', 'matear', 'verb', 'to drink mate', 'To sit and share mate, usually with other people.', 'informal', false, null, 'draft'),
  ('96f43774-d565-505f-99df-660fe6143598', 'no hay drama', 'phrase', 'no problem, it''s fine', null, 'informal', false, null, 'draft'),
  ('2d7d820e-8160-5cc4-826e-ef25d942a269', 'milanga', 'noun', 'breaded meat (short for milanesa)', 'A casual, warm word for milanesa.', 'informal', false, null, 'draft'),
  ('ba1839de-8bbc-5de4-8945-b00caa594abc', 'manteca', 'noun', 'butter', 'The Argentine word for butter.', 'neutral', false, null, 'draft'),
  ('374756fc-23d1-5d45-850a-0edaf8437296', 'choclo', 'noun', 'corn', 'The Argentine word for corn as food.', 'neutral', false, null, 'draft'),
  ('6a08e753-61db-5f38-b472-9ab2bc11716b', 'ananá', 'noun', 'pineapple', 'The Argentine word for pineapple.', 'neutral', false, null, 'draft'),
  ('6219ddc4-ef87-5e2a-9b95-ddc932831b58', 'fernet', 'noun', 'a bitter drink, mixed with cola', 'A strong bitter drink. Almost always drunk with cola and ice.', 'neutral', false, null, 'draft'),
  ('1fdde7ca-4c6c-5c97-8d79-0cf785a2770c', 'cursar', 'verb', 'to take (a class)', null, 'neutral', false, null, 'draft'),
  ('1ca270e8-46a5-5dee-9c4c-1a8b2dfec5f6', 'bocho', 'noun', 'a very smart person', null, 'informal', false, null, 'draft'),
  ('2c60a217-8fdb-5b80-9353-cf1b35c85522', 'birome', 'noun', 'pen', 'The everyday word for a pen in Argentina.', 'neutral', false, null, 'draft'),
  ('17768903-085e-5a45-865a-d80a3d843c50', 'quincho', 'noun', 'covered place with a grill, for eating with friends', null, 'neutral', false, null, 'draft'),
  ('57cfc85b-036b-5794-a615-b6e052f48dd6', 'funcar', 'verb', 'to work (a machine)', 'Casual. For machines and plans, not for people at a job.', 'informal', false, null, 'draft'),
  ('7680d35b-0fb4-5caa-86ea-6b5dd78ed7ca', 'pavada', 'noun', 'a silly, small thing', null, 'informal', false, null, 'draft'),
  ('da04c864-b1dc-53fd-8fbb-1f8c8b1a4309', 'placard', 'noun', 'closet', 'The built-in closet in a bedroom. Said "pla-CAR".', 'neutral', false, null, 'draft'),
  ('385506e8-52fd-5826-8e2f-d9186bdecc89', 'estufa', 'noun', 'heater', 'In Argentina it heats a room. It is not for cooking.', 'neutral', false, null, 'draft'),
  ('a549d629-d35e-5af7-bb67-9eecf2b17b75', 'documento', 'noun', 'ID', 'Your ID card. Hotels ask for "documento o pasaporte".', 'neutral', false, null, 'draft'),
  ('fc4f3285-34cd-5dea-8c46-e3de1d1f44f6', 'frazada', 'noun', 'blanket', null, 'neutral', false, null, 'draft'),
  ('f00960fe-de56-5606-8811-45539c52f8b3', 'rotisería', 'noun', 'shop that sells cooked food to take home', null, 'neutral', false, null, 'draft'),
  ('9dfdf8c1-e37e-5e73-8048-58ba3e527e47', 'tener pinta', 'phrase', 'to look good', null, 'informal', false, null, 'draft'),
  ('74f3c483-7711-5023-893c-9617ed576605', 'pochoclo', 'noun', 'popcorn', 'The Buenos Aires word for popcorn.', 'neutral', false, null, 'draft'),
  ('74d56c7d-8536-5486-ad3b-1453bea3fa2b', 'tener ganas de', 'phrase', 'to feel like (doing something)', null, 'neutral', false, null, 'draft'),
  ('1cb2a976-2a8b-5efd-8c86-59fe13bec8f1', 'escuchame', 'interj', 'listen', 'Said to get someone''s attention before you tell them something.', 'neutral', false, null, 'draft'),
  ('ea373b74-c077-5008-bcf0-8f827db10678', 'ponele onda', 'phrase', 'come on, make an effort', 'Said to someone who is being lazy or negative.', 'informal', false, null, 'draft'),
  ('a4990c03-2a6e-5802-80a5-30374068e5bb', 'tocar el timbre', 'phrase', 'to ring the bell', 'On a bondi you ring the bell to get off.', 'neutral', false, null, 'draft'),
  ('922b7b9a-0359-5482-9d47-13bdfaaa25b2', 'chofer', 'noun', 'driver', null, 'neutral', false, null, 'draft'),
  ('356cdb88-c26b-5270-b224-c7c7feaf5564', 'baúl', 'noun', 'trunk (of a car)', null, 'neutral', false, null, 'draft'),
  ('060d0aa6-d821-5839-9bdd-bcf0c00a3ad6', 'no te hagas problema', 'phrase', 'don''t worry about it', null, 'informal', false, null, 'draft'),
  ('773d46fa-1655-5ab1-ab52-6fab70e02d7b', 'guarda', 'interj', 'watch out!', '"Guarda con el perro" is watch out for the dog.', 'informal', false, null, 'draft'),
  ('a18945a8-70c3-590b-8f69-23c240ea8f24', 'mala leche', 'noun', 'bad luck', '"¡Qué mala leche!" is what bad luck.', 'informal', false, null, 'draft'),
  ('0f9169e6-fffb-5036-9ada-8895a0f4badf', 'medias', 'noun', 'socks', 'The only word for socks in Argentina.', 'neutral', false, null, 'draft'),
  ('e824c13a-b718-5de3-90fa-c3bc3c22b16d', 'facha', 'noun', 'looks, style', '"Tener facha" is to look good. "¡Qué facha!" is a compliment.', 'informal', false, null, 'draft'),
  ('7725d89a-4402-5e47-8da7-c27e84698d1d', 'pequeño', 'adj', 'small', 'People here say chico. You will see pequeño on signs and labels.', 'neutral', false, null, 'draft'),
  ('d7918259-accb-5ac2-a55d-238706275d58', 'recontra', 'adv', 'really, very very', 'Stronger than re: "recontra caro".', 'informal', false, null, 'draft'),
  ('a9637b08-8717-590a-ba2b-8044af2e1472', 'fachero', 'adj', 'good-looking, with style', null, 'informal', false, null, 'draft'),
  ('1adc74c1-545a-5789-bda5-0d719a35fa32', 'pulóver', 'noun', 'sweater', null, 'neutral', false, null, 'draft'),
  ('09e5a3fd-e932-5c99-9075-95d147112e3a', 'hacer factura', 'phrase', 'to give an invoice', 'Here factura is the paper that shows what you paid, not a pastry.', 'neutral', false, null, 'draft'),
  ('8ffcaa6d-2215-56a1-b5e4-4bc1eacbe821', 'palo', 'noun', 'a million pesos', null, 'informal', false, null, 'draft'),
  ('d5414cf2-c1ef-582f-9ddc-50eccbb4fe02', 'dólar blue', 'noun', 'the unofficial dollar price', 'The street price of the dollar, in the news every day.', 'neutral', false, null, 'draft'),
  ('231d0c39-841f-5969-8586-62b68c1f2716', 'me estás cargando', 'phrase', 'are you joking?', 'Said when you can''t believe something, like a price.', 'informal', false, null, 'draft'),
  ('df4fe39d-5c23-561a-87c7-6b74009ffa89', 'durante', 'prep', 'during', null, 'neutral', false, null, 'draft'),
  ('5db1d7e8-77aa-582f-850a-1f789789ab73', 'ponete las pilas', 'phrase', 'come on, get moving', 'Word for word: put your batteries in.', 'informal', false, null, 'draft'),
  ('b4cf5fe7-bd54-586a-8cc6-e72bafd26f09', 'la Selección', 'noun', 'the national team', 'The Argentina football team. When it plays, the country stops.', 'neutral', false, null, 'draft'),
  ('c4077242-8b42-58ad-bbef-69f22957da4b', 'al mango', 'phrase', 'very loud; as fast or as much as possible', null, 'informal', false, null, 'draft'),
  ('34ff3c2a-84a9-503c-9f68-8d066b1bdecd', 'prenderse', 'verb', 'to join in', '"¿Te prendés?" asks if you want to join a plan.', 'informal', false, null, 'draft'),
  ('a249eddb-9782-576a-b469-51f5f4090328', 'interesante', 'adj', 'interesting', null, 'neutral', false, null, 'draft'),
  ('4d2a81f7-61e9-5b3e-b1c4-2424c4d9d92e', 'copar', 'verb', 'to really like', 'Works like gustar: "me copa el tenis".', 'informal', false, null, 'draft'),
  ('9fb57bfa-34ed-5ca0-9e6b-1c390b633384', 'malla', 'noun', 'swimsuit', null, 'neutral', false, null, 'draft')
